/**
 * @file build/updaterLauncher.js
 * @description Builds `CueMol3 Updater.exe` into a packaged Windows app's resources.
 *
 * The self-updater (@cuemol/updater, win/) runs its install step elevated.
 * Elevating powershell.exe directly made the UAC prompt read "Windows
 * PowerShell", which says nothing about what is about to run; this launcher
 * exists so the prompt names CueMol3 instead (file name and FileDescription
 * "CueMol3 Updater", the app's icon; the publisher stays "Unknown" while the
 * app is unsigned). It only runs the PowerShell script whose path it is
 * given, hidden, and returns that script's exit code.
 *
 * Built with the same makensis electron-builder uses for the installer
 * (app-builder-lib's NSIS_PATH, downloaded into its cache on first use), so
 * neither the repository nor a build machine carries a binary for it.
 */
const { execFileSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

/** File name under resources/; WinInstaller looks for exactly this. */
const LAUNCHER_NAME = 'CueMol3 Updater.exe';

/** app-builder-lib as electron-builder resolves it (it is not a direct dependency). */
function appBuilderLib(rel) {
  const eb = require.resolve('electron-builder');
  return require(require.resolve(`app-builder-lib/${rel}`, { paths: [eb] }));
}

/**
 * The NSIS script. The launcher process is 32-bit, so file system
 * redirection is turned off before it starts PowerShell: a 32-bit
 * PowerShell would run a 32-bit reg.exe, which reads and writes the
 * WOW6432Node view instead of the installer's HKLM keys.
 */
function nsisScript({ out, icon, version, copyright }) {
  return `; Generated by build/updaterLauncher.js
Unicode true
!include FileFunc.nsh
!include x64.nsh
Name "CueMol3 Updater"
OutFile "${out}"
Icon "${icon}"
RequestExecutionLevel admin
SilentInstall silent
VIProductVersion "${version}"
VIAddVersionKey "ProductName" "CueMol3"
VIAddVersionKey "FileDescription" "CueMol3 Updater"
VIAddVersionKey "FileVersion" "${version}"
VIAddVersionKey "ProductVersion" "${version}"
VIAddVersionKey "LegalCopyright" "${copyright}"

Section
  \${GetParameters} $0
  StrCmp $0 "" 0 +3
    SetErrorLevel 2
    Quit
  \${If} \${RunningX64}
    \${DisableX64FSRedirection}
  \${EndIf}
  nsExec::Exec '"$SYSDIR\\WindowsPowerShell\\v1.0\\powershell.exe" -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File $0'
  Pop $1
  StrCmp $1 "error" 0 +2
    StrCpy $1 1
  SetErrorLevel $1
SectionEnd
`;
}

/**
 * Write the launcher into the packed app (Windows only).
 *
 * @param context - electron-builder's afterPack context
 * @returns the launcher's path, or null on other platforms
 */
async function buildUpdaterLauncher(context) {
  const { appOutDir, electronPlatformName, packager } = context;
  if (electronPlatformName !== 'win32') return null;
  const { NSIS_PATH } = appBuilderLib('out/targets/nsis/nsisUtil');
  const nsisDir = await NSIS_PATH();
  const makensis = path.join(nsisDir, process.platform === 'win32' ? 'Bin/makensis.exe' : 'linux/makensis');

  const out = path.join(appOutDir, 'resources', LAUNCHER_NAME);
  const work = fs.mkdtempSync(path.join(os.tmpdir(), 'cuemol-launcher-'));
  const nsi = path.join(work, 'launcher.nsi');
  fs.writeFileSync(
    nsi,
    nsisScript({
      out,
      icon: path.join(packager.info.buildResourcesDir, 'icon.ico'),
      version: packager.appInfo.getVersionInWeirdWindowsForm(),
      copyright: packager.appInfo.copyright,
    }),
  );
  execFileSync(makensis, ['/V2', '/INPUTCHARSET', 'UTF8', nsi], { stdio: 'inherit' });
  fs.rmSync(work, { recursive: true, force: true });
  if (!fs.existsSync(out)) throw new Error(`updaterLauncher: makensis did not write ${out}`);
  return out;
}

module.exports = { buildUpdaterLauncher, LAUNCHER_NAME };
